module multi_pipe_4bit(
    input clk, 
    input rst_n, 
    input [3:0] mul_a, 
    input [3:0] mul_b, 
    output [7:0] mul_out
);
// Extension of input signals
wire [7:0] mul_a_ext = 'd0 + mul_a;
wire [7:0] mul_b_ext = 'd0 + mul_b;
// Generate partial products
wire [7:0] partial_product_0 = (mul_b[0]) ? mul_a_ext : 'd0;
wire [7:0] partial_product_1 = (mul_b[1]) ? mul_a_ext << 1 : 'd0;
wire [7:0] partial_product_2 = (mul_b[2]) ? mul_a_ext << 2 : 'd0;
wire [7:0] partial_product_3 = (mul_b[3]) ? mul_a_ext << 3 : 'd0;
// Registers to store intermediate sums
reg [7:0] sum_tmp1;
reg [7:0] sum_tmp2;
// Sequential logic for stage 1
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sum_tmp1 <= 'd0;
        sum_tmp2 <= 'd0;
    end else begin
        sum_tmp1 <= partial_product_0 + partial_product_1;
        sum_tmp2 <= partial_product_2 + partial_product_3;
    end
end
// Final product calculation
reg [7:0] mul_out_reg;
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        mul_out_reg <= 'd0;
    end else begin
        mul_out_reg <= sum_tmp1 + sum_tmp2;
    end
end
assign mul_out = mul_out_reg;
endmodule
